$guard$;

-- 2. THE FIX
-- F-A orders_anon_insert (anon + authenticated INSERT WITH CHECK true): forged paid orders. Nobody but service_role / the SECURITY DEFINER fulfill_ticket_order may insert.
DROP POLICY orders_anon_insert ON public.event_orders;
-- F-B event_orders_organizer_update: an organizer could rewrite status / qr_token / checked_in_at / amount_cents of any order of their events. No client UPDATE is needed (check-in = 12A SECURITY DEFINER RPCs, refund = refund_ticket_order).
DROP POLICY event_orders_organizer_update ON public.event_orders;
-- F-C table ACL: ALL (incl. TRUNCATE, MAINTAIN, REFERENCES, TRIGGER, DELETE) for anon + authenticated. Remove everything, grant SELECT back (the surviving organizer_read / owner_read policies and the profile.html Tickets query need it; RLS still filters rows).
-- SELECT stays for anon on purpose: signed-out visitors of a profile run an event_orders SELECT today (profile.html loadTagged) and get an empty list; without the privilege they would get 42501. service_role / postgres are not touched.
REVOKE ALL ON TABLE public.event_orders FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.event_orders TO anon, authenticated;

-- 3. POST-CHECKS (assert; a failure rolls the whole transaction back). State S1.
DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'orders.relkind_rls' AS name, coalesce((SELECT c.relkind::text||'/'||c.relrowsecurity::text||'/'||c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.owner' AS name, coalesce((SELECT pg_get_userbyid(c.relowner)::text FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.columns_md5' AS name, coalesce((SELECT md5(string_agg(a.attname::text||':'||format_type(a.atttypid,a.atttypmod), ',' ORDER BY a.attname::text COLLATE "C")) FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attnum > 0 AND NOT a.attisdropped), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.indexes' AS name, coalesce((SELECT string_agg(i.indexname::text, ',' ORDER BY i.indexname::text COLLATE "C") FROM pg_indexes i WHERE i.schemaname = 'public' AND i.tablename = 'event_orders'), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.session_tier_unique_partial' AS name, coalesce((SELECT count(*)::text FROM pg_index i WHERE i.indrelid = 'public.event_orders'::regclass AND i.indisunique AND i.indpred IS NOT NULL AND (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(i.indkey::int2[]) WITH ORDINALITY k(attnum, ord) JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum) = 'stripe_session_id,tier_id'), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.constraints' AS name, coalesce((SELECT string_agg(x, ',' ORDER BY x COLLATE "C") FROM (SELECT c.contype::text||':'||coalesce((SELECT relname::text FROM pg_class WHERE oid = c.confrelid),'-')||':'||coalesce(nullif(c.confdeltype::text,' '),'-')||':'||(SELECT string_agg(a.attname::text, '+' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)) AS x FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype IN ('p','f','u')) z), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.check_count' AS name, coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c'), 'ABSENT') AS actual
