  UNION ALL SELECT 'refund.lang_ret' AS name, coalesce((SELECT (SELECT l.lanname FROM pg_language l WHERE l.oid=p.prolang)::text||'/'||p.prorettype::regtype::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.refund_ticket_order(text,text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'refund.acl_sorted' AS name, coalesce((SELECT coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.refund_ticket_order(text,text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'refund.exec_anon' AS name, coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.refund_ticket_order(text,text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'refund.exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.refund_ticket_order(text,text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'refund.exec_service_role' AS name, coalesce((SELECT has_function_privilege('service_role', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.refund_ticket_order(text,text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'refund.exec_public' AS name, coalesce((SELECT coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.refund_ticket_order(text,text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'deps.columns_present' AS name, coalesce((SELECT count(*)::text FROM (VALUES ('events','id'),('events','slug'),('events','title'),('events','owner_handle'),('app_users','id'),('app_users','handle'),('ticket_tiers','id'),('ticket_tiers','name'),('ticket_tiers','qty_sold')) v(t,c) WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.'||v.t) AND a.attname = v.c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'deps.my_handle_my_email' AS name, coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname IN ('my_handle','my_email')), 'ABSENT') AS actual
), e(name, expected) AS (VALUES
